<script>document.addEventListener('DOMContentLoaded',function(){const form=document.querySelector('form[action="{{ route('admission.store') }}"]');if(!form)return;const campus=form.querySelector('select[name="branch_id"]');if(!campus)return;const params=new URLSearchParams(window.location.search);const branch=params.get('branch_id');if(branch&&!campus.value)campus.value=branch;campus.addEventListener('change',function(){const url=new URL(window.location.href);if(this.value)url.searchParams.set('branch_id',this.value);else url.searchParams.delete('branch_id');url.hash='online-admission-form';window.location.href=url.toString();});});</script>
